class Dog {
    String name;
    Dog(String name) { this.name = name; }
}

void changeName(Dog d) {
    d.name = "Max";
}

void reassign(Dog d) {
    d = new Dog("Rex");
}

Dog myDog = new Dog("Buddy");
changeName(myDog);
System.out.println(myDog.name);

reassign(myDog);
System.out.println(myDog.name);
